public sealed class PollResult {public ClientReportProbe? Client {get;set;}public List<UpdateOutcome> Updates {get;set;}=new();public string TaskState {get;set;}="";public long TaskResult {get;set;}public bool AgentAlive {get;set;}public RemoteState? State {get;set;}public string Output {get;set;}="";}
